for coluna in numeric_features:
    serie = (
        X_train[
            coluna
        ]
        .dropna()
    )

    q1 = serie.quantile(
        0.25
    )

    q3 = serie.quantile(
        0.75
    )

    iqr = (
        q3 - q1
    )

    limite_inferior = (
        q1
        - 1.5 * iqr
    )

    limite_superior = (
        q3
        + 1.5 * iqr
    )

    fora_iqr = (
        (serie &lt; limite_inferior)
        |
        (serie &gt; limite_superior)
    )

    iqr_rows.append({
        "feature": coluna,
        "q1": q1,
        "q3": q3,
        "iqr": iqr,
        "limite_inferior": limite_inferior,
        "limite_superior": limite_superior,
        "n_fora_iqr": int(
            fora_iqr.sum()
        ),
        "percentual_fora_iqr":
            fora_iqr.mean()
            * 100,
    })

iqr_summary = (
    pd.DataFrame(
        iqr_rows
